<?php
$positiveSaveAction=$positiveSaveAction??'/quality-control/bacteriology/positive-samples/save';
$positiveCloseUrl=$positiveCloseUrl??$url('positives');
$positivePrintBase=$positivePrintBase??'/quality-control/bacteriology/positive-samples/form';
$records=$openPositive['records']?:[['id'=>null,'position'=>1,'include_in_form'=>1,'send_date'=>$openPositive['send_date'],'donation_number'=>$openPositive['donation_number'],'blood_component_id'=>$openPositive['source_component_id'],'hemocomponent'=>$openPositive['source_component'],'collection_date'=>$openPositive['collection_date'],'origin'=>$openPositive['origin'],'situation'=>'','storage_unit_id'=>null,'storage_location'=>'','reaction'=>'no','test_name'=>'Bacteriológico','bacteriology_date'=>date('Y-m-d'),'bacteriology_result'=>'positive','retest_result'=>$openPositive['source_result_stage']==='retest'?'positive':null,'identified_bacteria_initial'=>$openPositive['source_bacteria_initial']??'','identified_bacteria_retest'=>$openPositive['source_result_stage']==='retest'?($openPositive['source_bacteria_retest']??''):null]];
$locked=$openPositive['status']==='completed';
$h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
$unitTypes=['lcqh'=>'Laboratório','processing'=>'Processamento','transfusion_agency'=>'Agência Transfusional','management'=>'Gestão','other'=>'Unidade'];
?>
<dialog class="bact-positive-modal">
 <form method="post" action="<?=$h($positiveSaveAction)?>" id="positive-sample-form">
  <input type="hidden" name="_csrf" value="<?=$h($csrf)?>"><input type="hidden" name="positive_sample_id" value="<?=(int)$openPositive['id']?>">
  <header><div><span class="bact-kicker">POSITIVO CONFIRMADO</span><h2>Doação <?=$h($openPositive['donation_number'])?></h2><?php if(!empty($openPositive['patient_name'])):?><strong>Paciente: <?=$h($openPositive['patient_name'])?></strong><?php endif;?><p>Cadastre os demais hemocomponentes relacionados e gere os formulários de trabalho.</p></div><a class="bact-modal-close" href="<?=$h($positiveCloseUrl)?>" aria-label="Fechar">×</a></header>
  <div class="bact-modal-scroll"><div id="positive-records">
  <?php foreach($records as$i=>$r):$original=$i===0;?>
   <section class="bact-record <?=$original?'bact-record-original':''?>" data-record data-record-id="<?=(int)($r['id']??0)?>">
    <div class="bact-record-head"><h3>Registro <span><?=$i+1?></span><?=$original?'<small>Amostra positiva original</small>':''?></h3><?php if($original&&!$locked):?><input type="hidden" name="include_in_form[0]" value="1"><?php endif;?><label class="bact-check"><input type="checkbox" name="include_in_form[<?=$i?>]" value="1" <?=!empty($r['include_in_form'])?'checked':''?> <?=$locked||$original?'disabled':''?>> Incluir no formulário bacteriológico</label><?php if(!$original&&!empty($r['id'])):?><a target="_blank" class="button button-secondary button-compact" href="<?=$h($positivePrintBase)?>?id=<?=$openPositive['id']?>&record=<?=$r['id']?>">Imprimir formulário</a><?php elseif(!$original):?><button type="button" class="button button-secondary button-compact" disabled title="Salve o cadastro para habilitar a impressão">Imprimir formulário</button><?php endif;?></div>
    <div class="bact-record-grid">
     <label><span>Data envio</span><input type="date" name="send_date[]" value="<?=$h($r['send_date']??'')?>" <?=$locked?'readonly':''?>></label>
     <label><span>Nº da Doação</span><input name="donation_number[]" value="<?=$h($r['donation_number']??'')?>" <?=$locked?'readonly':''?>></label>
     <label><span>Hemocomponente</span><?php if($original&&!$locked):?><input type="hidden" name="blood_component_id[]" value="<?=(int)($r['blood_component_id']??0)?>"><?php endif;?><select name="blood_component_id[]" <?=$locked||$original?'disabled':''?>><option value="">Selecione</option><?php foreach($positiveComponents as$c):?><option value="<?=(int)$c['id']?>" <?=(string)($r['blood_component_id']??'')===(string)$c['id']?'selected':''?>><?=$h($c['code'].' — '.$c['name'])?></option><?php endforeach;?><?php if(empty($r['blood_component_id'])&&!empty($r['hemocomponent'])):?><option selected value=""><?=$h($r['hemocomponent'])?> (histórico)</option><?php endif;?></select><input type="hidden" name="hemocomponent[]" value="<?=$h($r['hemocomponent']??'')?>"></label>
     <label><span>Data de Coleta</span><input type="date" name="collection_date[]" value="<?=$h($r['collection_date']??'')?>" <?=$locked?'readonly':''?>></label>
     <label><span>Origem *</span><input name="origin[]" value="<?=$h($r['origin']??'')?>" <?=$locked?'readonly':''?>></label>
     <label><span>Situação *</span><select name="situation[]" <?=$locked?'disabled':''?>><option value="">Selecione</option><?php foreach(['in_stock'=>'Em estoque','distributed'=>'Distribuído','discarded'=>'Desprezado'] as$v=>$label):?><option value="<?=$v?>" <?=in_array(($r['situation']??''),[$v,$label],true)?'selected':''?>><?=$label?></option><?php endforeach;?></select></label>
     <label><span>Local de armazenamento *</span><select name="storage_unit_id[]" <?=$locked?'disabled':''?>><option value="">Selecione</option><?php foreach($positiveUnits as$u):?><option value="<?=(int)$u['id']?>" <?=(string)($r['storage_unit_id']??'')===(string)$u['id']?'selected':''?>><?=$h(($unitTypes[$u['unit_type']]??'Unidade').' — '.$u['name'])?></option><?php endforeach;?><?php if(empty($r['storage_unit_id'])&&!empty($r['storage_location'])):?><option selected value=""><?=$h($r['storage_location'])?> (histórico)</option><?php endif;?></select><input type="hidden" name="storage_location[]" value="<?=$h($r['storage_location']??'')?>"></label>
     <label><span>Reação *</span><select name="reaction[]" <?=$locked?'disabled':''?>><option value="no" <?=in_array(($r['reaction']??''),['','no','Não'],true)?'selected':''?>>Não</option><option value="yes" <?=in_array(($r['reaction']??''),['yes','Sim'],true)?'selected':''?>>Sim</option></select></label>
     <label><span>Teste</span><select name="test_name[]" <?=$locked?'disabled':''?>><option value="Bacteriológico" selected>Bacteriológico</option></select></label>
     <label><span>Data da Bact.</span><input type="date" name="bacteriology_date[]" value="<?=$h($r['bacteriology_date']??'')?>" <?=$locked?'readonly':''?>></label>
     <label><span>Resultado Bact.</span><select name="bacteriology_result[]" data-initial-result <?=$locked?'disabled':''?>><option value="">Selecione</option><option value="negative" <?=in_array(($r['bacteriology_result']??''),['negative','Negativo'],true)?'selected':''?>>Negativo</option><option value="positive" <?=in_array(($r['bacteriology_result']??''),['positive','Positivo','Positivo confirmado'],true)?'selected':''?>>Positivo</option></select></label>
     <label data-initial-bacteria-field><span><?=$original?'Bactéria identificada':'Bactéria identificada — resultado inicial'?> *</span><input name="identified_bacteria_initial[]" value="<?=$h($r['identified_bacteria_initial']??$r['identified_bacteria']??'')?>" <?=$locked?'readonly':''?>></label>
     <label data-retest-field <?=($original||($r['bacteriology_result']??'')!=='positive')?'hidden':''?>><span>Resultado do reteste *</span><select name="retest_result[]" data-retest-result <?=$locked?'disabled':''?>><option value="">Selecione</option><option value="negative" <?=in_array(($r['retest_result']??''),['negative','Negativo'],true)?'selected':''?>>Negativo</option><option value="positive" <?=in_array(($r['retest_result']??''),['positive','Positivo'],true)?'selected':''?>>Positivo</option></select></label>
     <label data-retest-bacteria-field <?=($r['retest_result']??'')!=='positive'?'hidden':''?>><span>Bactéria identificada — reteste *</span><input name="identified_bacteria_retest[]" value="<?=$h($r['identified_bacteria_retest']??(($r['retest_result']??'')==='positive'?($r['identified_bacteria']??''):''))?>" <?=$locked?'readonly':''?>></label>
    </div>
   </section>
  <?php endforeach;?></div>
   <?php if(!$locked):?><div class="bact-record-tools"><button type="button" class="button button-secondary" id="add-positive-record">Adicionar registro</button><button type="button" class="button button-secondary" id="remove-positive-record">Remover último registro</button></div><?php endif;?>
   <label class="bact-conclusion"><span>Conclusão *</span><textarea name="conclusion" maxlength="5000" <?=$locked?'readonly':''?>><?=$h($openPositive['conclusion']??'')?></textarea></label>
  </div>
  <footer><a class="button button-secondary" href="<?=$url('positives')?>">Fechar</a><button class="button button-secondary" type="button" id="print-selected">Imprimir selecionados</button><?php if(!$locked&&$canEdit):?><button class="button button-secondary">Salvar</button><button class="button" name="complete" value="1">Concluir</button><?php endif;?></footer>
 </form>
</dialog>
<script>
(()=>{const dialog=document.querySelector('.bact-positive-modal'),form=document.querySelector('#positive-sample-form'),box=document.querySelector('#positive-records'),add=document.querySelector('#add-positive-record'),remove=document.querySelector('#remove-positive-record'),print=document.querySelector('#print-selected');if(dialog&&!dialog.open)dialog.showModal();
const syncRecord=record=>{const original=record.classList.contains('bact-record-original'),initial=record.querySelector('[data-initial-result]'),initialBox=record.querySelector('[data-initial-bacteria-field]'),initialBacteria=record.querySelector('[name="identified_bacteria_initial[]"]'),retest=record.querySelector('[data-retest-result]'),retestField=record.querySelector('[data-retest-field]'),retestBox=record.querySelector('[data-retest-bacteria-field]'),retestBacteria=record.querySelector('[name="identified_bacteria_retest[]"]'),positive=initial.value==='positive',needsRetest=!original&&positive,needsRetestBacteria=positive&&retest.value==='positive';[initial,retest,initialBacteria,retestBacteria].forEach(field=>field.setCustomValidity(''));initialBox.hidden=!positive;initialBacteria.required=positive;retestField.hidden=!needsRetest;retest.required=needsRetest;if(!needsRetest)retest.value='';retestBox.hidden=!needsRetestBacteria;retestBacteria.required=needsRetestBacteria;if(!needsRetestBacteria)retestBacteria.value='';if(!positive)initialBacteria.value='';};
const bind=record=>{record.querySelector('[data-initial-result]').addEventListener('change',()=>syncRecord(record));record.querySelector('[data-retest-result]').addEventListener('change',()=>syncRecord(record));syncRecord(record)};const renumber=()=>box.querySelectorAll('[data-record]').forEach((r,i)=>{r.querySelector('h3 span').textContent=i+1;const check=r.querySelector('.bact-check input');check.name=`include_in_form[${i}]`});box.querySelectorAll('[data-record]').forEach(bind);
if(add)add.onclick=()=>{const source=box.lastElementChild,clone=source.cloneNode(true);clone.classList.remove('bact-record-original');clone.dataset.recordId='0';clone.querySelector('h3 small')?.remove();clone.querySelectorAll('input[type="hidden"][name="blood_component_id[]"],.bact-record-head>input[type="hidden"]').forEach(input=>input.remove());clone.querySelectorAll('input').forEach(input=>{if(input.type==='checkbox'){input.checked=true;input.disabled=false}else if(input.name==='donation_number[]')input.value='<?=$h($openPositive['donation_number'])?>';else if(input.name==='send_date[]')input.value='<?=$h($openPositive['send_date'])?>';else if(input.name==='collection_date[]')input.value='<?=$h($openPositive['collection_date'])?>';else if(input.name==='origin[]')input.value='<?=$h($openPositive['origin'])?>';else if(input.name==='hemocomponent[]'||input.name==='storage_location[]')input.value='';else input.value=''});clone.querySelectorAll('select').forEach(select=>{select.disabled=false;if(select.name==='reaction[]')select.value='no';else if(select.name==='test_name[]')select.value='Bacteriológico';else select.value=''});clone.querySelector('.bact-record-head .button')?.remove();const disabled=document.createElement('button');disabled.type='button';disabled.disabled=true;disabled.className='button button-secondary button-compact';disabled.textContent='Imprimir formulário';disabled.title='Salve o cadastro para habilitar a impressão';clone.querySelector('.bact-record-head').append(disabled);box.append(clone);bind(clone);renumber();clone.scrollIntoView({behavior:'smooth',block:'center'})};if(remove)remove.onclick=()=>{if(box.children.length>1){box.lastElementChild.remove();renumber()}};form.addEventListener('submit',e=>{if(e.submitter?.name!=='complete')return;box.querySelectorAll('[data-record]').forEach((record,i)=>{const number=i+1,initial=record.querySelector('[data-initial-result]'),initialBacteria=record.querySelector('[name="identified_bacteria_initial[]"]'),retest=record.querySelector('[data-retest-result]'),retestBacteria=record.querySelector('[name="identified_bacteria_retest[]"]');initial.setCustomValidity(i===0||initial.value?'':`Registro ${number}: informe o resultado bacteriológico.`);initialBacteria.setCustomValidity(initial.value==='positive'&&!initialBacteria.value.trim()?(i===0?'Registro 1: informe a bactéria identificada.':`Registro ${number}: informe a bactéria identificada do resultado inicial.`):'');retest.setCustomValidity(i>0&&initial.value==='positive'&&!retest.value?`Registro ${number}: informe o resultado do reteste.`:'');retestBacteria.setCustomValidity(initial.value==='positive'&&retest.value==='positive'&&!retestBacteria.value.trim()?`Registro ${number}: informe a bactéria identificada do reteste positivo.`:'')})});print.onclick=()=>{const ids=[...box.querySelectorAll('[data-record]')].slice(1).filter(r=>r.querySelector('.bact-check input')?.checked&&Number(r.dataset.recordId)>0).map(r=>r.dataset.recordId);if(!ids.length){alert('Selecione e salve ao menos um registro adicional antes de imprimir.');return}window.open(`/quality-control/bacteriology/positive-samples/form?id=<?=(int)$openPositive['id']?>&records=${ids.join(',')}`,'_blank','noopener')}})();
</script>
